import math

def power(a, b, m):
    """Computes (a^b) % m"""
    return pow(a, b, m)

M = 10000
base = 3

# Euler's totient function phi(10000) = 4000. The order L must divide 4000.
phi_M = 4000

# Find all divisors of 4000
def get_divisors(n):
    divs = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

divisors_4000 = get_divisors(phi_M)

# Test divisors in increasing order to find the order L
order_L = None
for d in divisors_4000:
    if power(base, d, M) == 1:
        order_L = d
        break

print(f"The multiplicative order L of 3 modulo 10000 is: {order_L}")
